"""Render a benchmark run (JSON) as docs/BENCHMARK.md."""

from __future__ import annotations

from typing import Any


def _f(v: Any, digits: int = 2, suffix: str = "") -> str:
    if v is None:
        return "—"
    if isinstance(v, float):
        return f"{v:.{digits}f}{suffix}"
    return f"{v:,}{suffix}" if isinstance(v, int) else f"{v}{suffix}"


def render_markdown(run: dict[str, Any], source: str) -> str:
    hw = run["hardware"]
    s = run["settings"]
    lines = [
        "# Engine benchmark",
        "",
        "Generated by `benchmarks/run_benchmark.py` from a real run; do not edit by hand.",
        f"Raw data: [`{source}`](../{source}).",
        "",
        f"- **Hardware:** {hw.get('gpu', 'CPU')} ({_f(hw.get('gpu_memory_gb'), 1)} GB), driver {hw.get('driver', '—')}, "
        f"{hw.get('os')}, torch {hw.get('torch', '—')} / CUDA {hw.get('cuda', '—')}",
        f"- **Run:** {run['started_at'][:16].replace('T', ' ')} UTC, {s['repeats']} repeats per script "
        f"(median reported), {len(next(iter(run['engines'].values()))['scripts'])} scripts",
        (
            f"- **Quality check:** {s['asr_model']} transcribes each render; WER/CER against the text the "
            "engine was asked to say (after the pipeline's abbreviation expansion). This measures intelligibility, "
            "not naturalness."
            if s["asr_model"]
            else "- **Quality check:** skipped for this run."
        ),
        "",
        "## Summary",
        "",
        "| Engine | Voice | Load (s) | Peak VRAM (MB) | Synthesis RTF (median) | × real time (overall) | Short-line latency (ms) | WER | CER |",
        "|---|---|---:|---:|---:|---:|---:|---:|---:|",
    ]
    for name, e in run["engines"].items():
        sm = e["summary"]
        lines.append(
            f"| {name} | {e['voice']} | {_f(e['load_ms'] / 1000, 1)} | {_f(e['peak_vram_mb'], 0)} | {_f(sm['rtf_p50'], 3)} "
            f"| {_f(sm['x_realtime'], 1, '×')} | {_f(sm['latency_ms_short'])} | {_f(sm['wer'] * 100 if sm['wer'] is not None else None, 1, '%')} "
            f"| {_f(sm['cer'] * 100 if sm['cer'] is not None else None, 1, '%')} |"
        )
    lines += [
        "",
        "RTF = synthesis time ÷ audio duration (lower is faster; below 1 is faster than real time). "
        "Load time includes reading weights and engine warm-up. Peak VRAM is PyTorch's peak allocation "
        "above the baseline while that engine ran.",
        "",
        "## Per script",
        "",
        "Each script is rendered `repeats` times; the range shows run-to-run spread for identical input.",
        "",
    ]
    for name, e in run["engines"].items():
        lines += [
            f"### {name}",
            "",
            "| Script | Kind | Chars | Chunks | Audio (s) | Synthesis p50 (ms) | Range over repeats (ms) | RTF | WER | CER |",
            "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|",
        ]
        for r in e["scripts"]:
            wer = r.get("wer")
            cer = r.get("cer")
            lines.append(
                f"| {r['id']} | {r['kind']} | {r['chars']} | {r['chunks']} | {_f(r['audio_seconds'])} | {_f(r['synthesis_ms_p50'])} "
                f"| {_f(min(r['synthesis_ms']))}–{_f(max(r['synthesis_ms']))} "
                f"| {_f(r['rtf'], 3)} | {_f(wer * 100 if wer is not None else None, 1, '%')} | {_f(cer * 100 if cer is not None else None, 1, '%')} |"
            )
        lines.append("")
    return "\n".join(lines)
